<?php
namespace Tests\Unit;use App\Models\{TransportDocument,TransportDocumentType};use Carbon\Carbon;use Tests\TestCase;
class TransportDocumentStatusTest extends TestCase {protected function tearDown():void{Carbon::setTestNow();parent::tearDown();}public function test_document_without_expiration_never_expires():void{$d=new TransportDocument(['expires_at'=>null]);$this->assertSame('valid',$d->control_status);}public function test_warning_window_is_configurable():void{Carbon::setTestNow('2026-08-18');$type=new TransportDocumentType(['warning_days'=>15]);$d=new TransportDocument(['expires_at'=>'2026-08-28']);$d->setRelation('type',$type);$this->assertSame('expiring',$d->control_status);$expired=new TransportDocument(['expires_at'=>'2026-08-17']);$expired->setRelation('type',$type);$this->assertSame('expired',$expired->control_status);}}
